# -*- coding: utf-8 -*-
# 해외 라디오 보류 방송 다시 점검 (10/19 점검에서 '보류'였던 493개)
#  · 방송마다 두 가지 이름표(앱 재생기 VLC · 브라우저)로 물어보고, 하나라도 소리가 나오면 '살아남'
#  · 안 나온 방송은 3분 뒤 한 번 더 → 두 번 다 안 나오면 '빼기'
#  · 결과: "보류 방송 다시 점검.csv" + "block.json"(예전 465개 + 이번에 뺄 방송) → R2 paransori/radio/block.json 에 덮어 올리기
#  · 이 컴퓨터(인터넷 되는 곳)에서: python check_radio4.py  (10분쯤 걸려요)
import base64, csv, json, ssl, sys, time, urllib.request
from concurrent.futures import ThreadPoolExecutor
sys.stdout.reconfigure(encoding='utf-8')

D = json.loads(base64.b64decode('').decode('utf-8'))
HOLD, OLD = D['hold'], D['old']
CTX = ssl._create_unverified_context()  # 앱 재생기는 인증서 검사를 안 해서 같게
UAS = ['VLC/3.0.20 LibVLC/3.0.20', 'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36']
TIMEOUT = 20


def looks_audio(data):
    h = data[:64].lstrip().lower()
    return (h.startswith(b'#extm3u') or h.startswith(b'[playlist]') or h.startswith(b'id3') or h.startswith(b'oggs')
            or data[:2] in (b'\xff\xfb', b'\xff\xf3', b'\xff\xf2', b'\xff\xf1', b'\xff\xf9'))


def once(url, ua):
    try:
        req = urllib.request.Request(url, headers={'User-Agent': ua, 'Icy-MetaData': '0'})
        with urllib.request.urlopen(req, timeout=TIMEOUT, context=CTX) as r:
            ct = (r.headers.get('Content-Type') or '').lower()
            data = r.read(16384)
            if not data:
                return False, '받은 내용 없음'
            if 'text/html' in ct and not looks_audio(data):
                return False, '웹페이지'
            return True, ct or '소리'
    except urllib.error.HTTPError as e:
        return False, f'서버 오류 {e.code}'
    except Exception as e:
        m = str(e)
        if 'ICY 200' in m:
            return True, 'ICY'
        if 'timed out' in m:
            return False, f'{TIMEOUT}초 안에 응답 없음'
        return False, m[:60]


def check(url):
    why = ''
    for ua in UAS:
        ok, why = once(url, ua)
        if ok:
            return True, why
    return False, why


def main():
    print(f'보류 방송 {len(HOLD)}개 다시 확인할게요 (몇 분 걸려요)')
    with ThreadPoolExecutor(40) as ex:
        res = list(ex.map(lambda h: check(h[2]), HOLD))
    again = [i for i, r in enumerate(res) if not r[0]]
    print(f'1번째: 나옴 {len(HOLD) - len(again)}개 · 안 나옴 {len(again)}개')
    if again:
        print('안 나온 방송은 3분 뒤 한 번 더 확인할게요')
        time.sleep(180)
        with ThreadPoolExecutor(40) as ex:
            res2 = list(ex.map(lambda i: check(HOLD[i][2]), again))
        for i, r in zip(again, res2):
            res[i] = r
    out_rows, remove = [], []
    for h, (ok, why) in zip(HOLD, res):
        verdict = '살아남' if ok else '빼기'
        if not ok:
            remove.append(h[3])
        out_rows.append([h[0], h[1], verdict, h[4], why, h[2], h[3]])
    with open('보류 방송 다시 점검.csv', 'w', newline='', encoding='utf-8-sig') as f:
        w = csv.writer(f)
        w.writerow(['나라', '방송 이름', '판정', '10/19 이유', '이번 이유', '주소', '방송 번호(uuid)'])
        w.writerows(out_rows)
    uu = sorted(set(OLD) | set(remove))
    with open('block.json', 'w', encoding='utf-8') as f:
        json.dump({'updated': time.strftime('%Y-%m-%d'), 'uuids': uu}, f, ensure_ascii=False)
    print(f'\n결과: 살아남 {len(HOLD) - len(remove)}개 · 빼기 {len(remove)}개')
    print(f'block.json: 예전 {len(OLD)}개 + 이번 {len(remove)}개 = {len(uu)}개')
    print('→ "보류 방송 다시 점검.csv", "block.json" 저장했어요')
    print('→ block.json 을 R2 paransori/radio/ 에 덮어 올리면 끝 (앱 업데이트 필요 없음)')


main()
